CREATE TABLE IF NOT EXISTS settings(id VARCHAR(50) PRIMARY KEY,key VARCHAR(255) UNIQUE NOT NULL,value TEXT);
INSERT INTO settings(id,key,value) VALUES('1','shop_name','Moon Cosmetics & Beauty Shop'),('2','shop_logo','assets/moon_logo.png'),('3','print_footer','Thank you for shopping with us!') ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value;
CREATE TABLE IF NOT EXISTS categories(id VARCHAR(50) PRIMARY KEY,name VARCHAR(150) UNIQUE NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS products(id VARCHAR(50) PRIMARY KEY,name VARCHAR(255) NOT NULL,brand VARCHAR(150),category_id VARCHAR(50) REFERENCES categories(id),barcode VARCHAR(100) UNIQUE,purchase_price NUMERIC(12,2) NOT NULL DEFAULT 0,retail_price NUMERIC(12,2) NOT NULL DEFAULT 0,wholesale_price NUMERIC(12,2) NOT NULL DEFAULT 0,min_stock INTEGER NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS product_batches(id VARCHAR(50) PRIMARY KEY,product_id VARCHAR(50) NOT NULL REFERENCES products(id) ON DELETE CASCADE,batch_no VARCHAR(100),purchase_price NUMERIC(12,2) NOT NULL DEFAULT 0,quantity INTEGER NOT NULL DEFAULT 0,expiry_date DATE,created_at TIMESTAMP NOT NULL DEFAULT NOW(),is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS customers(id VARCHAR(50) PRIMARY KEY,name VARCHAR(255) NOT NULL,phone VARCHAR(50),address TEXT,opening_balance NUMERIC(12,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS suppliers(id VARCHAR(50) PRIMARY KEY,name VARCHAR(255) NOT NULL,phone VARCHAR(50),address TEXT,opening_balance NUMERIC(12,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS accounts(id VARCHAR(50) PRIMARY KEY,name VARCHAR(100) NOT NULL,type VARCHAR(50) NOT NULL,balance NUMERIC(14,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sales(id VARCHAR(50) PRIMARY KEY,invoice_number BIGSERIAL UNIQUE,customer_id VARCHAR(50) REFERENCES customers(id),subtotal NUMERIC(12,2) NOT NULL DEFAULT 0,discount NUMERIC(12,2) NOT NULL DEFAULT 0,extra_charges NUMERIC(12,2) NOT NULL DEFAULT 0,total_amount NUMERIC(12,2) NOT NULL DEFAULT 0,paid_amount NUMERIC(12,2) NOT NULL DEFAULT 0,payment_status VARCHAR(20) NOT NULL DEFAULT 'cash',payment_account_id VARCHAR(50) REFERENCES accounts(id),date TIMESTAMP NOT NULL DEFAULT NOW(),notes TEXT);
CREATE TABLE IF NOT EXISTS sale_items(id VARCHAR(50) PRIMARY KEY,sale_id VARCHAR(50) NOT NULL REFERENCES sales(id) ON DELETE CASCADE,product_id VARCHAR(50) NOT NULL REFERENCES products(id),batch_id VARCHAR(50) REFERENCES product_batches(id),quantity INTEGER NOT NULL,purchase_price NUMERIC(12,2) NOT NULL DEFAULT 0,sale_price NUMERIC(12,2) NOT NULL DEFAULT 0,discount NUMERIC(12,2) NOT NULL DEFAULT 0,profit NUMERIC(12,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS purchases(id VARCHAR(50) PRIMARY KEY,purchase_number BIGSERIAL UNIQUE,supplier_id VARCHAR(50) REFERENCES suppliers(id),total_amount NUMERIC(12,2) NOT NULL DEFAULT 0,paid_amount NUMERIC(12,2) NOT NULL DEFAULT 0,date TIMESTAMP NOT NULL DEFAULT NOW(),notes TEXT);
CREATE TABLE IF NOT EXISTS purchase_items(id VARCHAR(50) PRIMARY KEY,purchase_id VARCHAR(50) NOT NULL REFERENCES purchases(id) ON DELETE CASCADE,product_id VARCHAR(50) NOT NULL REFERENCES products(id),batch_id VARCHAR(50) REFERENCES product_batches(id),quantity INTEGER NOT NULL,purchase_price NUMERIC(12,2) NOT NULL DEFAULT 0,total NUMERIC(12,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS expenses(id VARCHAR(50) PRIMARY KEY,category VARCHAR(100) NOT NULL,account_id VARCHAR(50) REFERENCES accounts(id),amount NUMERIC(12,2) NOT NULL,date TIMESTAMP NOT NULL DEFAULT NOW(),description TEXT);
CREATE TABLE IF NOT EXISTS customer_ledger(id VARCHAR(50) PRIMARY KEY,customer_id VARCHAR(50) NOT NULL REFERENCES customers(id),type VARCHAR(30) NOT NULL,amount NUMERIC(12,2) NOT NULL,reference_id VARCHAR(50),date TIMESTAMP NOT NULL DEFAULT NOW(),notes TEXT);
CREATE TABLE IF NOT EXISTS supplier_ledger(id VARCHAR(50) PRIMARY KEY,supplier_id VARCHAR(50) NOT NULL REFERENCES suppliers(id),type VARCHAR(30) NOT NULL,amount NUMERIC(12,2) NOT NULL,reference_id VARCHAR(50),date TIMESTAMP NOT NULL DEFAULT NOW(),notes TEXT);
CREATE OR REPLACE VIEW product_stock AS SELECT p.id product_id,p.name product_name,COALESCE(SUM(pb.quantity) FILTER(WHERE pb.is_active=TRUE),0)::INT current_stock FROM products p LEFT JOIN product_batches pb ON pb.product_id=p.id GROUP BY p.id,p.name;
